      SUBROUTINE LATOUT      INCLUDE 'DTF.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'PRINTC.CIN'      INCLUDE 'PRINTL.CIN'C      WRITE (NOUT,*) '^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^'      WRITE (NOUT,*) 'LATDEF [',LATDEFL,'] <',     1	             LATDEFFILE(1:LLATDEFF),'> ',LLATDEFF      WRITE (NOUT,*) 'MAD [',MADL,'] <',     1	             MADFILE(1:LMADF),'> ',LMADF      WRITE (NOUT,*) 'TRANSPORT [',TRANSPORTL,'] <',     1	             TRANSPORTFILE(1:LTRANSPORTF),'> ',LTRANSPORTF      WRITE (NOUT,*) 'STRUCT [',STRUCTL,'] <',     1	             STRUCTFILE(1:LSTRUCTF),'> ', LSTRUCTF      WRITE (NOUT,*) 'ACAD [',ACADL,'] <',     1	             ACADFILE(1:LACADF),'> ',LACADF      WRITE (NOUT,*) '^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^'C      IF (FILEL) THEN        CALL WTOUT      ENDIF      IF (LATDEFL) THEN        IF (LLATDEFF .GT. 0) THEN	  UFILEOUT = LATDEFFILE(1:LLATDEFF)//'.TOUT.LATDEF'	  CALL ELIMTB (UFILEOUT,LOUT)          CAll LCTABS(UFILEOUT)          OPEN (UNIT=35,FILE=UFILEOUT(1:LOUT),     1	    FORM='FORMATTED',STATUS='UNKNOWN',IOSTAT=IOS)          IF (IOS .NE. 0) THEN            PRINT *,'FAILED TO OPEN LATDEF ',     1        'OUTPUT FILE. IOS=',IOS            WRITE (NOUT,*) 'FAILED TO OPEN LATDEF ',     1        'OUTPUT FILE. IOS=',IOS          END IF        END IF        CALL WLATDEF      ENDIFC      IF (MADL) THEN        IF (LMADF .GT. 0) THEN          UFILEOUT = MADFILE(1:LMADF)//'.TOUT.MAD'          CALL LCTABS(UFILEOUT)          CALL ELIMTB (UFILEOUT,LOUT)          OPEN (UNIT=36,FILE=UFILEOUT(1:LOUT),     1      FORM='FORMATTED',STATUS='UNKNOWN',IOSTAT=IOS)          IF (IOS .NE. 0) THEN            PRINT *,'FAILED TO OPEN MAD ',     1        'OUTPUT FILE. IOS=',IOS            WRITE (NOUT,*) 'FAILED TO OPEN MAD ',     1        'OUTPUT FILE. IOS=',IOS          END IF        END IF        CALL WMAD      END IFC        IF (TRANSPORTL) THEN          IF (LTRANSPORTF .GT. 0) THEN            UFILEOUT=TRANSPORTFILE(1:LTRANSPORTF)//     1        '.TOUT.TRAN'            CALL LCTABS(UFILEOUT)            CALL ELIMTB (UFILEOUT,LOUT)            OPEN (UNIT=37,FILE=UFILEOUT(1:LOUT),     1        FORM='FORMATTED',STATUS='UNKNOWN',IOSTAT=IOS)            IF (IOS .NE. 0) THEN              PRINT *,'FAILED TO OPEN TRANSPORT ',     1          'OUTPUT FILE. IOS=',IOS              WRITE (NOUT,*) 'FAILED TO OPEN TRANSPORT ',     1          'OUTPUT FILE. IOS=',IOS            END IF          END IF          CALL WTRAN	ENDIFC        IF (STRUCTL) THEN          IF (LSTRUCTF .GT. 0) THEN            UFILEOUT=STRUCTFILE(1:LSTRUCTF)//'.TOUT.STRUCT'            CALL ELIMTB (UFILEOUT,LOUT)            CALL LCTABS(UFILEOUT)            OPEN (UNIT=38,FILE=UFILEOUT(1:LOUT),     1        FORM='FORMATTED',STATUS='UNKNOWN',IOSTAT=IOS)            IF (IOS .NE. 0) THEN              PRINT *,'FAILED TO OPEN STRUCT ',     1          'OUTPUT FILE. IOS=',IOS              WRITE (NOUT,*) 'FAILED TO OPEN STRUCT ',     1          'OUTPUT FILE. IOS=',IOS            END IF          END IF          CALL WSTRUCT	END IFC      IF (ACADL) THEN        IF (LACADF .GT. 0) THEN          UFILEOUT=ACADFILE(1:LACADF)//'.TOUT.SCR'          CALL ELIMTB (UFILEOUT,LOUT)          CALL LCTABS(UFILEOUT)          OPEN (UNIT=39,FILE=UFILEOUT(1:LOUT),     1      FORM='FORMATTED',STATUS='UNKNOWN',IOSTAT=IOS)          IF (IOS .NE. 0) THEN            PRINT *,'FAILED TO OPEN AUTO-CAD ',     1        'OUTPUT FILE. IOS=',IOS            WRITE (NOUT,*) 'FAILED TO OPEN AUTO-CAD ',     1        'OUTPUT FILE. IOS=',IOS          END IF        END IF        CALL WACAD      ENDIF      END